// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, pinLink, getLinksList, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Declaration of variables
    const pinnedOnly = "true";
    const sort = "0";

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "Skyramp Pin Lifecycle"
        },
        "name": "Skyramp Pin Lifecycle Link",
        "url": "https://example.com/skyramp-pin-lifecycle"
    }`;

    const linksPostResponse = await createLink(client, headers, linksPostRequestBody);

    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("Skyramp Pin Lifecycle Link");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("https://example.com/skyramp-pin-lifecycle");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collection.name"), 'collection name').toBe("Skyramp Pin Lifecycle");
    expect(getResponseValue(linksPostResponse, "response.id"), 'link id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.createdAt"), 'createdAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const createdLinkId = getResponseValue(linksPostResponse, "response.id");
    const callerUserId = getResponseValue(linksPostResponse, "response.collection.ownerId");
    const createdCollectionId = getResponseValue(linksPostResponse, "response.collection.id");

    const pinPatchResponse = await pinLink(client, headers, createdLinkId);

    expect(pinPatchResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(pinPatchResponse, "response.id"), 'pinned link id').toBe(createdLinkId);
    expect(getResponseValue(pinPatchResponse, "response.name"), 'name').toBe("Skyramp Pin Lifecycle Link");
    expect(getResponseValue(pinPatchResponse, "response.url"), 'url').toBe("https://example.com/skyramp-pin-lifecycle");
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy").length, 'pinnedBy holds exactly one pin after pinning').toBe(1);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.0.id"), 'pinnedBy names the calling user').toBe(callerUserId);
    expect(getResponseValue(pinPatchResponse, "response.pinnedBy.1"), 'pinnedBy has no second entry').toBeNull();
    expect(getResponseValue(pinPatchResponse, "response.updatedAt"), 'updatedAt').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const linksGetResponse = await getLinksList(client, headers, pinnedOnly, sort);

    expect(linksGetResponse.statusCode, 'status code').toBe(200);

    const pinnedLinks = getResponseValue(linksGetResponse, "response");
    expect(Array.isArray(pinnedLinks), 'pinnedOnly returns an array').toBe(true);
    expect(pinnedLinks.map((l: any) => l.id), 'pinnedOnly list contains the link that was just pinned').toContain(createdLinkId);
    const pinnedEntry = pinnedLinks.find((l: any) => l.id === createdLinkId);
    expect(pinnedEntry.name, 'pinned entry name').toBe("Skyramp Pin Lifecycle Link");
    expect(pinnedEntry.url, 'pinned entry url').toBe("https://example.com/skyramp-pin-lifecycle");
    expect(pinnedEntry.pinnedBy.map((u: any) => u.id), 'pinned entry is pinned by the calling user').toContain(callerUserId);

    const pinPatch1Response = await pinLink(client, headers, createdLinkId);

    expect(pinPatch1Response.statusCode, 'status code').toBe(200);

    expect(getResponseValue(pinPatch1Response, "response.id"), 'unpinned link id').toBe(createdLinkId);
    expect(getResponseValue(pinPatch1Response, "response.name"), 'name').toBe("Skyramp Pin Lifecycle Link");
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy").length, 'pinnedBy is empty after the second toggle').toBe(0);
    expect(getResponseValue(pinPatch1Response, "response.pinnedBy.0"), 'pinnedBy has no entries after unpinning').toBeNull();

    const linksGet1Response = await getLinksList(client, headers, pinnedOnly, sort);

    expect(linksGet1Response.statusCode, 'status code').toBe(200);

    const pinnedLinksAfterUnpin = getResponseValue(linksGet1Response, "response");
    expect(Array.isArray(pinnedLinksAfterUnpin), 'pinnedOnly returns an array').toBe(true);
    expect(pinnedLinksAfterUnpin.map((l: any) => l.id), 'unpinned link has dropped out of the pinnedOnly list').not.toContain(createdLinkId);

    const linksLinksDeleteResponse = await deleteLink(client, headers, createdLinkId);

    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'deleted link id').toBe(createdLinkId);

    const collectionDeleteResponse = await deleteCollection(client, headers, createdCollectionId);

    expect(collectionDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionDeleteResponse, "response.id"), 'deleted collection id').toBe(createdCollectionId);
});
